-- 0. Never queue behind a long-running query
SET lock_timeout = '3s';

-- 1. Instant: add an unvalidated check
ALTER TABLE users
  ADD CONSTRAINT users_phone_not_null
  CHECK (phone IS NOT NULL) NOT VALID;

-- 2. Validates existing rows with SHARE UPDATE EXCLUSIVE (reads/writes continue)
ALTER TABLE users VALIDATE CONSTRAINT users_phone_not_null;

-- 3. PostgreSQL 12+ recognises the proven check and skips a new full scan
ALTER TABLE users ALTER COLUMN phone SET NOT NULL;

-- 4. The check has done its job and can go
ALTER TABLE users DROP CONSTRAINT users_phone_not_null;

-- On PostgreSQL 12+, SET NOT NULL alone no longer rewrites the table,
-- but it still scans to verify, so step 3 is fast only after step 2.
